      "ap.bookGreet": "收到！结合你确认的就诊方案：{project}｜{doctor}｜{clinic}｜{date}就诊，我为你整理了预约流程，您可以按照如下指引完成操作。",
      "ap.bk1Title": "完成外籍账号注册",
