      "ap.bk1p2": "请选择护照作为有效就诊证件，填写本人真实姓名、护照信息、常用微信联系方式，完成账号实名认证。外籍用户无需国内身份证，护照建档即可正常挂号、到店就诊、开具正规病历。",
      "ap.bk1p3": "请您放心，注册填写的所有信息均严格遵循医疗隐私保护规范，仅用于院内建档、预约核验及就诊追溯，不会对外泄露、挪作他用，全程隐私加密保护。",
