      "ap.bk3p1": "用注册好的账号登录卓正医疗官方APP，您可以在「我的 - 诊疗服务记录 - 受理中」查找到此次预约信息。如需调整预约，请根据AI陪诊助手的指引，在应用内重新预约。",
      "ap.bk3p2": "预约将在支付完成后立刻生效，锁定医生档期。目前线上支持微信支付、支付宝、国际信用卡（VISA/Mastercard）直接支付，无需提前兑换人民币。",
