      "ap.bk4p1": "预约确认无误后，可以在卓正医疗APP「我的 - 外籍患者陪诊」中，查看就诊通知和就诊准备清单。",
      "ap.bk4li1": "双语就诊通知：包含门店精准地址、营业时间、到店核验流程；",
