      "ap.bkWechatTip": "以上流程也可以在微信小程序「卓正医疗」内完成。考虑到外籍用户不熟悉中国大陆的医疗规范和就医流程，您也可以通过以下方式联系我们。",
      "ap.bkContactTitle": "欢迎添加微信：",
