      "ap.g1_2": "フェイシャル洗浄＋肌修復：¥800–1500｜€105–195",
      "ap.g1_3": "敏感肌ケア：¥1000–1800｜€130–235",
      "ap.group2Title": "2. 低侵襲ケア（肌質・軽いアンチエイジング）",
      "ap.g2_1": "基本水光注射（乾燥肌救世主・ツヤ）：¥2500–4000｜€325–520",
      "ap.g2_2": "細シワ改善：¥3000–5000｜€390–650",
