      "ap.depts": ["歯科（インプラント・矯正・クリーニング・根管治療等）", "美容医療（注射・フォトフェイシャル・スキンケア）", "小児科・子どもの健康（ワクチン・発育評価）", "個別健診（プレミアム定制プラン）", "皮膚科（アレルギー・湿疹・皮膚トラブル）", "眼科（視力検査・ドライアイ）", "耳鼻咽喉科（鼻炎・聴力検査等）", "理学療法・リハビリ（スポーツ障害・術後リハビリ）", "産婦人科（妊娠前検査・妊婦健診・相談）", "その他の診療"],
