      "ap.dn.beauty1Learn": "仕組み：1回約60〜90分。流れ：口腔検査で虫歯・歯周病を排除 → 歯面清掃 → 防湿下にホワイトニングジェル塗布 → 青色光触媒（3〜4ラウンド、各8〜15分）→ フッ化ナトリウムで知覚過敏処理 → 術後の色調維持指導。<br>効果：その場で2〜6段階の色調改善、コーヒー・紅茶・喫煙・加齢による黄ばみに対応。過酸化水素濃度は管理され、脱敏処理との併用で術後の知覚過敏は軽微。<br>適応：外因性着色が中心で歯質が健康な方。重度フッ素症・テトラサイクリン歯は個別プランが必要。妊娠中・矯正装置着用中・未治療の虫歯は延期。",
