      "ap.dn.beauty3Learn": "仕組み：1回20〜40分。流れ：小児口腔検査 → Tell-Show-Do 法で適応 → フッ素/乳歯補綴/抜歯（必要に応じ）→ 歯磨き・食習慣指導 → 定期検診計画。<br>効果：乳歯虫歯の早期治療で永久歯胚と顎の発育を保護。フッ素がエナメル質の耐酸性を強化。誘導型診療で歯科恐怖を軽減。<br>適応：3〜12歳の初診・定期虫歯予防・乳歯問題の早期介入。急性の痛みや外傷は優先対応。",
