      "ap.pd.projA1Desc": "標準化された測定器具で身長・体重・頭囲を正確に記録し、WHOおよび中国0–18歳の成長基準と照合した個別成長曲線を作成。成長速度と栄養状態を評価し、低身長・過体重・肥満などの逸脱を特定します。医師が両親の身長から遺伝的目標身長と骨年齢（必要時）を総合判断し、食事・運動・睡眠の介入プランを提示。単回約30–45分、その場で評価アドバイスを提供。身長・体重に不安のある保護者、国際移動する子ども、入学前のベースライン記録に。",
      "ap.pd.projA2Name": "発達マイルストーン評価",
