      "ap.pd.projA2Desc": "粗大運動・微細運動・言語・社会性の4領域を、国際標準の発達尺度（ASQ、Denver IIなど）と医師の臨床観察で体系的に評価し、神経心理発達が月齢・年齢に適合しているか判断します。言語の遅れ、運動発達の遅れ、社会性の課題などを早期発見し、早期介入につなげます。単回約30–45分、評価後に書面レポートと家庭トレーニングのアドバイスを提供。0–6歳の定期スクリーニング、早産児の経過観察、「周りより遅いかも」の早期確認に。",
      "ap.pd.projA3Name": "栄養・生活指導",
